"""Authorized targeted collector shutdown, then unchanged RAM-only protocol."""
import base64,hashlib,importlib.util,json,os,pathlib,platform,signal,subprocess,sys,time
P=pathlib.Path
PAYLOAD={'ram052.py': {'sha256': '7f24b7566b1de814d912cc037adfd59e93a297ef2809f4ac41db84f8194f2356', 'base64': ''}, 'stop_collector052.py': {'sha256': 'cfc919bccf887e32a63cbbaea600026e9748a63d39c569523bc95924ad96fe36', 'base64': ''}}
def sha(b):return hashlib.sha256(b).hexdigest()
def main():
 result={'experiment':'Y_STOP_COLLECTOR_RAM052','success':False,'aenvChanged':False,'frequencyChanged':False,'stopAudit':{}};root=P('/home/jwk/xy-memory-control-20261117-Y-052');child=None
 try:
  assert os.getuid()==os.geteuid()==0 and platform.node()=='debian' and platform.machine()=='x86_64';os.umask(0o077)
  assert P('/proc/sys/kernel/random/boot_id').read_text().strip()=='d005bda4-518d-4766-b704-259df7bae4f9'
  assert not root.exists();root.mkdir(mode=0o700)
  for name,item in PAYLOAD.items():
   raw=base64.b64decode(item['base64'],validate=True);assert sha(raw)==item['sha256'];(root/name).write_bytes(raw)
  spec=importlib.util.spec_from_file_location('targeted_stop',root/'stop_collector052.py');stopper=importlib.util.module_from_spec(spec);spec.loader.exec_module(stopper)
  try:stopper.stop(result['stopAudit'])
  finally:(root/'stop-audit.json').write_text(json.dumps(result['stopAudit'],indent=2)+'\n')
  assert result['stopAudit']['success']
  for _ in range(4):
   active=[r for r in stopper.all_procs().values() if r['comm'] in ('lat_probe','bw_probe','perf','multiload','multichase') and r['state']!='Z'];assert not active,'Another active probe/perf remains; no benchmark started'
   time.sleep(2)
  env={'PATH':'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','HOME':'/root','LANG':'C.UTF-8','LC_ALL':'C.UTF-8'}
  with (root/'ram.stdout.log').open('xb') as out,(root/'ram.stderr.log').open('xb') as err:
   child=subprocess.Popen(['/usr/bin/python3','-I','-B',str(root/'ram052.py'),'Y'],env=env,stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
   code=child.wait(timeout=800);child=None
  assert code==0,'RAM runner process failed; retain logs'
  ram=json.loads((root/'ram.stdout.log').read_text());assert ram['experiment']=='XY_MEMORY052';result['ramResult']=ram;result['success']=ram['success'];result['ramWorkerSha256']=PAYLOAD['ram052.py']['sha256'];result['stopWorkerSha256']=PAYLOAD['stop_collector052.py']['sha256']
 except BaseException as e:result['error']=type(e).__name__+': '+str(e)[:1200]
 finally:
  if child is not None and child.poll() is None:
   os.killpg(child.pid,signal.SIGINT)
   try:child.wait(timeout=20)
   except subprocess.TimeoutExpired:os.killpg(child.pid,signal.SIGKILL);child.wait(timeout=5)
  if root.exists():(root/'result-descriptor.json').write_text(json.dumps({k:v for k,v in result.items() if k!='ramResult'},indent=2)+'\n')
  raw=json.dumps(result,separators=(',',':'));assert len(raw.encode())<800000;print(raw,flush=True)
if __name__=='__main__':main()
